using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Linq;
namespace KeyJaya {public static class StandaloneTests {
 static int passed,failed;static void Check(bool value,string name){if(value)passed++;else{failed++;if(failed<50)Console.WriteLine("FAIL "+name);}}static void Equal(string a,string b,string name){Check(a==b,name+" expected="+a+" actual="+b);}
 static void Reject(string path,string text){File.WriteAllText(path,text,new UTF8Encoding(false));try{Configuration.Read(path);Check(false,"invalid configuration accepted "+text);}catch(InvalidDataException){passed++;}}
 static string Route(Core c,string input){InputState s=new InputState();string output=null;foreach(char x in input){string trigger=s.Type(x,c);if(trigger!=null)output=c.Trigger(trigger)??output;}return output;}
 [STAThread]public static int Main(string[] args){Console.OutputEncoding=new UTF8Encoding(false);string scratch=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[0])),"standalone-test-artifacts",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(scratch);string file=Path.Combine(scratch,"personal.yml");
  File.WriteAllText(file,"matches:\n  - trigger: ':quote'\n    replace: 'It''s nice'\n  - trigger: ':sign'\n    replace: |-\n      Best wishes,\n      Your name\n  - trigger: ':fold'\n    replace: >-\n      first\n      second\n  - trigger: ':date'\n    replace: '{{date:%Y-%m-%d}}'\n",new UTF8Encoding(false));var parsed=Configuration.Read(file);Equal("It's nice",parsed[":quote"],"apostrophe");Equal("Best wishes,\nYour name",parsed[":sign"],"multiline");Equal("first second",parsed[":fold"],"folded");Equal("2026-10-11",Configuration.Expand(parsed[":date"],new DateTime(2026,10,11)),"date");Equal("2026 26 10 11 13 01 14 15 PM Oct October Sun Sunday %",Configuration.Date("%Y %y %m %d %H %I %M %S %p %b %B %a %A %%",new DateTime(2026,10,11,13,14,15)),"date formats");
  Random random=new Random(170);for(int i=0;i<1000;i++){string value="Unicode rājä \\\" ' & < >\t\n"+random.Next()+" # literal";var rows=new Dictionary<string,string>{{":test"+i,value}};Configuration.Write(file,rows);Equal(value,Configuration.Read(file)[":test"+i],"roundtrip escaped configuration "+i);}
  foreach(string bad in new[]{"", "trigger: ':x'\nreplace: x", "matches:\n - trigger: ':x'\n   replace: x\n - trigger: ':x'\n   replace: y", "matches:\n - trigger: 'two words'\n   replace: x", "matches:\n - trigger: ':x'\n   replace: '{{output}}'", "matches:\n - trigger: ':x'\n   replace: '{{date:%Q}}'", "matches:\n - trigger: ':x'\n   replace: x\n   word: true", "matches:\n - trigger: ':x'\n   replace: x\n   vars:\n     - name: command", "matches:\n - trigger: ':x'\n   replace: \"broken", "matches:\n - trigger: ':x'", "matches: []\nmatches: []"})Reject(file,bad);
   var all=new Dictionary<string,string>{{":hello","Hello!"},{":Hello","Different personal replacement"},{":sign","First line\nSecond line"},{"HT>","Custom Haridāsa"}};Configuration.Write(file,all);string root=Path.Combine(scratch,"app");Directory.CreateDirectory(Configuration.Folder(root));Directory.CreateDirectory(Path.Combine(root,"state"));Directory.CreateDirectory(Path.Combine(root,"data"));foreach(string data in Directory.GetFiles(Path.Combine(args[0],"data")))File.Copy(data,Path.Combine(root,"data",Path.GetFileName(data)));File.Copy(file,Configuration.Personal(root));
  using(Core c=new Core(root)){
    Equal("Hello!",c.TriggerWithObservedCase(":hello",":Hello"),"Word capitalization preserves the physically typed personal trigger");Equal("Custom Haridāsa",c.TriggerWithObservedCase("HT>","Ht>"),"Word capitalization preserves short-trigger literal replacement");
   Equal("Hello!",Route(c,"Earlier an age since :hello"),"colon trigger full token");Equal("First line\nSecond line",Route(c,":sign"),"multiline trigger");Equal("Custom Haridāsa",Route(c,"HT>"),"user override precedence");Check(c.IsDirectTrigger("HT>"),"short trigger direct ownership");Equal(null,Route(c,"x:hello"),"no suffix expansion within preceding word");Equal(null,Route(c,"an> age> since>"),"English untouched");Equal(null,Route(c,"Earlier 123#"),"full number token");Equal(null,Route(c,"Earlier 123rd#"),"ordinal trigger");Equal(null,Route(c,"1,234#"),"comma number");Equal(null,Route(c,"x123#"),"embedded number untouched");Equal(null,Route(c,"12,34#"),"bad grouped number untouched");Equal(null,Route(c,"1.5#"),"decimal untouched");Equal(null,Route(c,"-1#"),"negative untouched");Equal(null,Route(c,new string('x',161)+":hello"),"overflow no suffix editing");
   for(int n=0;n<10000;n++){string value=n.ToString();Equal(null,Route(c,"prefix an age since "+value+"#"),"retired number route "+value);Equal(null,Route(c,value+"th#"),"retired ordinal route "+value);Equal(Numbers.Words(value,false),c.ConvertHighlighted(value,"unicode"),"Ctrl number "+value);Equal(Numbers.Words(value,true),c.ConvertHighlighted(value+"th","unicode"),"Ctrl ordinal "+value);}
   foreach(string raw in new[]{"18446744073709551616#","1,00#","0,0000#","12,345,67#","foo12#","#","1st:","1 : :","1\n#"})Equal(null,Route(c,raw),"invalid numeric ownership "+raw);
   c.RememberSpelling("rāja","räjä","balaram","auto");c.FinishSpellingChoice();Check(File.Exists(Path.Combine(root,"state","preferred-spellings.tsv")),"preferences in state folder");
   Reject(Configuration.Personal(root),"matches:\n - trigger: ':bad'\n   replace: '{{script}}'");try{using(Core replacement=Core.Reload(c,root)){}Check(false,"invalid reload accepted");}catch(InvalidDataException){passed++;}Equal("Hello!",c.Trigger(":hello"),"invalid reload leaves active engine working");
   File.Move(Configuration.Personal(root),Configuration.Personal(root)+".bad");try{using(Core replacement=Core.Reload(c,root)){}Check(false,"missing config accepted");}catch(InvalidDataException){passed++;}Equal("Hello!",c.Trigger(":hello"),"missing config preserves active engine");
   all[":hello"]="Changed!";Configuration.Write(Configuration.Personal(root),all);c.RememberSpelling("rāja","räjä","balaram","auto");c.FinishSpellingChoice();c.RememberSpelling("rāja","räjä","balaram","auto");using(Core replacement=Core.Reload(c,root)){Equal("Changed!",replacement.Trigger(":hello"),"valid reload applies exact edited trigger");Equal("rājā",replacement.Convert("rāja","unicode"),"reload retains pending third preference vote");}

  }
  InputState undo=new InputState();undo.RecordReplacement("prana>","prāṇa",new IntPtr(7));Equal("prana>",undo.UndoOriginal,"explicit trigger retains undo");Equal("prāṇa",undo.UndoOutput,"explicit output ownership");undo.RecordReplacement("doesnt ","doesn’t ",new IntPtr(7),true);Equal(null,undo.UndoOriginal,"auto contraction cannot revert");Equal(null,undo.UndoOutput,"no stale manual undo after correction");undo.RecordReplacement("räja","rāja",new IntPtr(7));Equal("räja",undo.UndoOriginal,"clipboard conversion retains undo");
  Equal("zero",Numbers.Single("0"),"zero");Equal("zeroth",Numbers.Single("0th"),"zeroth");Equal("twenty-first",Numbers.Single("21st"),"twenty first");Equal("one million",Numbers.Single("1,000,000"),"million");Equal("eighteen quintillion four hundred forty-six quadrillion seven hundred forty-four trillion seventy-three billion seven hundred nine million five hundred fifty-one thousand six hundred fifteen",Numbers.Single("18446744073709551615"),"maximum uint64");

  // The canonical YAML is authoritative: removing a built-in must not reveal a hidden default.
  string editable=Path.Combine(scratch,"editable");Directory.CreateDirectory(Configuration.Folder(editable));Directory.CreateDirectory(Path.Combine(editable,"data"));Directory.CreateDirectory(Path.Combine(editable,"state"));
  foreach(string data in Directory.GetFiles(Path.Combine(args[0],"data")))File.Copy(data,Path.Combine(editable,"data",Path.GetFileName(data)));
  Configuration.Write(Path.Combine(Configuration.Folder(editable),Configuration.PersonalFile),new Dictionary<string,string>{{"HT>","Legacy override"}});
  var editableRows=new Dictionary<string,string>{{"HT>","Haridāsa Ṭhākura"},{":mine","My replacement"}};Configuration.Write(Configuration.Short(editable),editableRows);
  Equal(Configuration.Short(editable),Configuration.Personal(editable),"editor opens canonical short-trigger YAML");
  using(Core editableCore=new Core(editable)){
   Equal("Haridāsa Ṭhākura",editableCore.Trigger("HT>"),"editable built-in active");
   editableRows["HT>"]="Changed short replacement";Configuration.Write(Configuration.Short(editable),editableRows);
   using(Core changed=Core.Reload(editableCore,editable))Equal("Changed short replacement",changed.Trigger("HT>"),"edit applies after reload");
   editableRows.Remove("HT>");Configuration.Write(Configuration.Short(editable),editableRows);
   using(Core deleted=Core.Reload(editableCore,editable)){Equal(null,deleted.Trigger("HT>"),"deletion disables built-in despite legacy override");Equal("My replacement",deleted.Trigger(":mine"),"unrelated custom trigger preserved");}
  }
  using(Core restarted=new Core(editable))Equal(null,restarted.Trigger("HT>"),"deletion persists after restart");
  Console.WriteLine("PASS: "+passed+" FAIL: "+failed);return failed==0?0:1;
 }
}}
